\begin{equation}
    \label{prob:main-det}
    \min_{x\in\RR^d} \Psi(x) = f(x) + \phi(x) \qquad\mbox{with}\qquad f(x) = \frac{1}{n}\sum_{i=1}^n f_i(x),
\end{equation}

where $\phi(x)$ is a convex but possibly non-differentiable function, while $f$ and each $f_i$ are nonconvex and continuously differentiable.


\begin{equation}
    \label{defn:BPG-standard}
    x_{k+1} = \mathbf{T}_{\phi,h}^\lambda\big(x_k, \nabla f(x_k)\big)\qquad\mbox{with}\qquad \mathbf{T}_{\phi,h}^\lambda (x,v) := \argmin_{y\in\RR^d}\,\, y^\top v + \phi(y) + \lambda^{-1}D_h(y,x),\vspace{-0.1cm}
\end{equation}

where $D_h(y,x):=h(y)-\nabla h(x)^\top(y-x)-h(x)$ stands for the Bregman divergence induced by $h$. 


\begin{equation}
    \label{defn:GradMap-BPG}
    \mathcal{G}_{\phi,h}^\lambda(x):= \frac{x-\mathbf{T}_{\phi,h}^\lambda\big(x,\nabla f(x)\big)}{\lambda}.  
\end{equation}

\noindent\textbf{Notations.} For $\forall x\in\RR^d$, We default $\|x\|:=\sqrt{x^\top x}$  the $\ell_2$-norm, and we denote $\|x\|_1:=\sum_i|x_i|$ as the $\ell_1$-norm. For a matrix $X\in\RR^{d\times d}$, we use $\lambda_{\max}(X)$ and $\lambda_{\min}(X)$ to denote the maximal and minimal eigenvalues of $X$, respectively. And we use $\|X\|$ to denote the $\ell_2$-operator norm of $X$. When $X$ is positive semidefinite, we write $X\succeq0$, and we have $\|X\| = \lambda_{\max}(X)$ in this case. For any set $\cX$, 
we denote $\mathrm{id}_{\cX}(\cdot)$ as the indicator function of the set.  Namely, $\mathrm{id}_{\cX}(x)=0$ if $x\in\cX$ and $\mathrm{id}_{\cX}(x) = +\infty$ if $x\notin\cX$. We denote the interior of $\cX$ as $\mathrm{int}(\cX)$ and we denote the boundary of $\cX$ as $\partial \cX$. We denote $[n]:=\{1,2,\cdots,n\}$. For any vector $x\in\RR^d$, the function $\mathrm{sign}: \RR^d\to\RR^d$ returns a sign vector of $x$. That is, for any $s=\mathrm{sign}(x)$, its $i$-th element satisfies $s_i=1$ if $x_i\geq0$ and $s_i=-1$ if $x_i<0$, for any $1\leq i\leq d$. Because many literature use the terminology $L$-smooth to denote $L$-Lipschitz continuity of the gradient, we will use ``continuously differentiable'' instead of ``smooth''  to avoid confusion. 


\begin{assumption}[Smooth adaptability, \cite{bolte2018first}]
    \label{assumption:L-smad}
    Let $f$ and $h$ be twice continuously differentiable in $\mathbb{R}^d$, and let $h$ be strictly convex. Then we assume $f$ is $L$-smooth adaptable to $h$ for some positive constant $L>0$. In other words, both  $Lh+f$ and $Lh-f$ are convex functions. 
\end{assumption}

\noindent Given the twice continuous differentiability of $f$ and $h$, Assumption \ref{assumption:L-smad} can be equivalently written  as 
\begin{equation}
    \label{asmp:L-smad-alt}
    -L\nabla^2h(x)\preceq \nabla^2 f(x)\preceq L\nabla^2h(x),\,\, \forall x\in\RR^d.
\end{equation}

\begin{equation}
    \label{defn:condition}
    \mu_h(\mathcal{X}) \,=\, \min_{x\in\cX}\,\lambda_{\min}\big(\nabla^2 h(x)\big),\quad L_h(\mathcal{X}) \,=\, \max_{x\in\cX}\,\lambda_{\max}\big(\nabla^2 h(x)\big),\quad\mbox{and}\quad \kappa_h(\cX) := \frac{L_h(\cX)}{\mu_h(\cX)}.
\end{equation}

\begin{assumption}[Kernel-conditioning]
    \label{assumption:kernel-conditioning}
    For any $\delta>0$, there exists a constant $\kappa_h^\delta>0$ such that  $$\sup_{\mathcal{X}\subseteq\mathbb{R}^d}\Big\{\kappa_h(\mathcal{X}):\mathrm{diam}(\mathcal{X})\leq \delta\Big\}\leq \kappa_h^\delta,$$
where $\mathrm{diam}(\cX):=\sup\{\|x-y\|: x,y\in\cX\}$ denotes the diameter of the set $\cX$.
\end{assumption}

\begin{assumption}[Strong convexity]
    \label{assumption:SC}
    The kernel $h$ is $\mu$-strongly convex for some $\mu>0$.
\end{assumption}

\begin{assumption}
    \label{assumption:L-smad-finite-sum}
    For each $i\in[n]$, $f_i$ is $L_i$-smooth adaptable to $h$ for some positive constant $L_{i}>0$. Denote $L:=\sqrt{\frac{1}{n}\sum_i^nL_i^2}$, then $f$ is $L$-smooth adaptable to $h$. 
\end{assumption}

Throughout Section \ref{section:VR}, we will use Assumption \ref{assumption:L-smad-finite-sum}, Assumption \ref{assumption:kernel-conditioning}, and Assumption \ref{assumption:SC}, and we propose a stochastic variance reduced BPG method with epoch-wise bounds  in Algorithm \ref{algorithm:proxSARAH}. 


\begin{algorithm2e}
\caption{Stochastic variance reduced BPG method with epoch bounds} 
\label{algorithm:proxSARAH}
\textbf{Input:} Initial point $x_{1,0}$, constant $\delta$, epoch length $\tau$, step size $\eta$,  interpolation factor $\gamma\in(0,1]$.   \\
\For{$s=1,2,3,\cdots,S$}{
    Construct a convex set $\mathcal{X}_s\supseteq {B}(x_{s,0},\delta/2)$ such that $\kappa_h(\mathcal{X}_s)\leq \kappa_h^\delta$\,.  \\\textcolor{gray}{//**Proposition \ref{proposition: Poly-kernel-condition} suggests $\mathcal{X}_s= B\left(x_{s,0},\max\left\{\frac{1}{2r},\frac{\|x_{s,0}\|}{2r+1}\right\}\right)$ for polynomial kernel**//}

    \For{$k = 0,1,2,\cdots,\tau-1$}{  
    If $k==0$, compute $v_{s,0}= \nabla f(x_{s,0}) = \frac{1}{n}\sum_{i=1}^n\nabla f_i(x_{s,0})$.\\
    If $k\geq 1$, uniformly sample a mini-batch $\mathcal{B}_{s,k}\subseteq[n]$  with replacement, compute  
    \begin{equation}
        \label{alg:sarah-small}
        v_{s,k} = v_{s,k-1} + \frac{1}{|\mathcal{B}_{s,k}|}\sum_{\xi\in\mathcal{B}_{s,k}} \Big(\nabla f_\xi(x_{s,k})-\nabla f_\xi(x_{s,k-1})\Big)\,.
    \end{equation}\\

    Denote $\mathrm{id}_{\cX_s}$ the indicator function of $\cX_s$. Compute the BPG update with 


    \begin{equation}
        \label{alg:proxSARAH-update}
        \bar{x}_{s,k+1} =  \Tshe(x_{s,k},v_{s,k})\qquad\mbox{and}\qquad x_{s,k+1} = (1-\gamma)x_{s,k}+\gamma\bar{x}_{s,k+1}\vspace{-0.1cm}
    \end{equation}  \\ 
    \textbf{if}\,\,\,$\mathrm{dist}(x_{s,k+1},\partial \cX_s) \leq \delta/4$\,\,\,\textbf{then}\,\,\,\textbf{break} the inner forloop.
    } 
    Set $\tau_s=k+1$ and $x_{s+1,0} = x_{s,\tau_s}$. 
    } 
\end{algorithm2e}

\begin{equation} 
        \label{alg:sarah-update}
        \bar{x}_{s,k+1} = \argmin_{x\in\mathcal{X}_s}\,\, \langle v_{s,k}, x\rangle + \phi(x) +  \frac{1}{\eta}D_h(x,x_{s,k}) . 
    \end{equation}

Define the true \emph{restricted} primal gradient mapping in epoch $s$ as  
\begin{equation}
    \label{defn:restricted-grd-mapping}
    \cGshe(x_{s,k}):=\frac{x_{s,k}-\hat{x}_{s,k+1}}{\eta}\quad\mbox{with}\quad\hat{x}_{s,k+1}:=\Tshe\big(x_{s,k},\nabla f(x_{s,k})\big),
\end{equation}

where by ``restricted'' we means this primal gradient mapping incorporates the indicator function of the set constraint $x\in\cX_s$.
Compared to the $\bar{x}_{s,k+1}$ in Algorithm \ref{algorithm:proxSARAH}, $\hat{x}_{s,k+1}$ is constructed with the true gradient $\nabla f(x_{s,k})$.  For this restricted primal gradient mapping, the following lemma holds true.

