\begin{theorem}
    \label{theorem:proxSARAH-finite}
    For any constant batch size $|\mathcal{B}_{s,k}|=b\in[n]$, let us set the epoch length as $\tau = \lceil n/b\rceil$, step size $\eta = \frac{\sqrt{2\tau}}{\sqrt{7\tau}+\sqrt{2b}}$, interpolation coefficient $\gamma = \frac{\sqrt{b}}{L\kappa_h^\delta\sqrt{\tau}}$, and total epoch number $S = \big\lceil\frac{16\Delta_\Psi}{\tau\gamma\eta\mu\epsilon}\big\rceil$. Suppose the target accuracy satisfies $\epsilon\leq \frac{\delta^2}{16}\cdot\min\big\{\frac{L^2(\kappa_h^\delta)^2}{b\tau},\frac{1}{9\eta^2}\big\} = O(1/n)$ and let $x_{\mathrm{out}}$ be uniformly randomly selected from all iterations, then there is a high probability event $\mathcal{A}$ such that $$\mathbb{E}\Big[\big\|\cGphe(x_{\mathrm{out}})\big\|^2 \,\big|\, \mathcal{A}\Big]\leq 4\epsilon\qquad\mbox{and}\qquad \mathrm{Prob}\left(\mathcal{A}\right)\geq1 - \frac{8\eta\tau b\epsilon}{L^2(\kappa_h^\delta)^2\delta^2}-\frac{4\sqrt{\epsilon}}{\delta}.$$
    In particular, $\mathrm{Prob}\left(\mathcal{A}\right) \geq 1-O(n\epsilon+\sqrt{\epsilon})\to1$ as $\epsilon\to0.$ Suppose we take the batch size $b=O(n^\alpha)$, $\alpha\in[0,1]$, then the total number of samples consumed is $O\big(\epsilon^{-1}\cdot n^{\max\{\alpha,\frac{1}{2}\}}\big)$.
\end{theorem}

