\begin{lemma}[Extended descent lemma, \cite{bolte2018first}]
    \label{lemma:descent-lemma}
    Suppose $f$ and $h$ satisfy Assumption \ref{assumption:L-smad} for some constant $L>0$, then for any $\forall x,y\in\RR^d$, it holds that 
    $$|f(x)-f(y)-\langle\nabla f(y),x-y\rangle|\leq LD_h(x,y).$$
\end{lemma}

\begin{lemma}
    \label{lemma:grd-vs-grdmap}
    For any $x,v\in\RR^d$ and any strictly convex kernel $h$, denote $x_\lambda^+(v) := \mathbf{T}_{\phi,h}^\lambda(x,v)$.  Let $[x,x_\lambda^+(v)]$ be the line segment between $x_\lambda^+(v)$ and $x$, then there exists $u\in\partial\phi(x_\lambda^+(v))$ such that  
    \begin{equation}
        \mu_h\big([x,x_\lambda^+(v)]\big)\cdot \|x-x_\lambda^+(v)\|\leq\lambda\|v+u\|\leq L_h\big([x,x_\lambda^+(v)]\big)\cdot \|x-x_\lambda^+(v)\|\,,\nonumber
    \end{equation} 
    \begin{equation}
        \sqrt{2\mu_h\big([x,x_\lambda^+(v)]\big)\cdot D_h(x_\lambda^+(v),x)}\leq \lambda\|v+u\|\leq \sqrt{2L_h\big([x,x_\lambda^+(v)]\big)\cdot D_h(x_\lambda^+(v),x)}\,\,.\nonumber
    \end{equation}   
\end{lemma}

\begin{proposition}[Lipschitz-like bound] 
    \label{proposition:Lipschitz} 
    Suppose $f$ is $L$-smooth adaptable to some KC-regular kernel $h$. Let $\delta>0$ and let $\cX$ be any convex set with $\mathrm{diam}(\cX)\leq \delta$. Then for any $x,y\in\cX$, and an arbitrary interpolation point $z_\theta := \theta x + (1-\theta)y$ with $ \theta\in[0,1]$, we have  
    \begin{equation}
        \label{prop:Lipschitz}
        \frac{\|\nabla f(z_\theta)-\nabla f(y)\|^2}{2L^2\mu_h(\cX)}\leq  \theta^2\kappa_h^2(\cX) D_h(x,y),
    \end{equation}
    where by KC-regularity, we know the constant upper bound $\kappa_h(\cX)\leq \kappa_h^\delta$ always hold. 
\end{proposition}

\begin{lemma}
    \label{lemma:restricted-grd-mapping} 
    Let $\cGshe(x_{s,k})$, $\hat{x}_{s,k+1}$ and $\bar{x}_{s,k+1}$ be defined by \eqref{defn:restricted-grd-mapping} and \eqref{alg:sarah-update}, respectively. Then 
    \begin{eqnarray}
    \label{lm:grad-mapping} 
        \big\|\cGshe(x_{s,k})\big\|^2 \leq \frac{2\|x_{s,k}-\bar{x}_{s,k+1}\|^2}{\eta^2} + \frac{2\|\mathcal{E}_{s,k}\|^2}{\mu_h^2(\mathcal{X}_s)},
    \end{eqnarray} 
    where $\mathcal{E}_{s,k} = \nabla f(x_{s,k})-v_{s,k}$ denotes the gradient estimation error at $x_{s,k}$.
\end{lemma}

\begin{lemma}
\label{lemma:descent-proxSARAH-finite}
    Let $\{x_{s,k}\}_{k=0}^{\tau_s}$ be the $s$-th epoch of Algorithm \ref{algorithm:proxSARAH}, then  we have 
    \begin{eqnarray}
    \Psi(x_{s,k+1})\leq \Psi(x_{s,k})-\frac{\gamma\eta\mu_h(\mathcal{X}_s)}{8}\big\|\cGshe(x_{s,k})\big\|^2\!-\!\bigg(\frac{\gamma}{\eta}- L\kappa_h^\delta\gamma^2\!\bigg)\!D_h(\bar{x}_{s,k+1},x_{s,k}) \!+\!\frac{5\gamma\eta\|\mathcal{E}_{s,k}\|^2}{4\mu_h(\mathcal{X}_s)}.\,\nonumber
    \end{eqnarray} 
\end{lemma}

\begin{lemma}
    \label{lemma:err-sarah} 
    Let $\{x_{s,k}\}_{k=0}^{\tau_s}$ be the $s$-th epoch of Algorithm \ref{algorithm:proxSARAH}. Given any batch size $b>0$, if we set $|\mathcal{B}_{s,k}|=b$ for $k=1,\cdots,\tau_s-1$. Then conditioning on the initial point $x_{s,0}$ of the epoch, we have
    \begin{eqnarray}
    \label{lm:err-sarah-0}
    \mathbb{E}\left[\frac{\|\mathcal{E}_{s,k}\|^2}{\mu_h(\mathcal{X}_s)}\,\Big|\, x_{s,0}\right] \leq  \frac{2\gamma^2L^2(\kappa_h^\delta)^2}{b}\mathbb{E}\bigg[\sum_{j=0}^{k-1} D_h(\bar{x}_{s,j+1},x_{s,j})\,\big|\,x_{s,0}\bigg]\,, 
\end{eqnarray}
as long as $h$ satisfies the kernel conditioning regularity assumption in $\cX_s$. 
\end{lemma}

\begin{proof}
    By \cite[Lemma 2]{pham2020proxsarah}, it is not hard to obtain that 
    \begin{equation}
        \label{lm:err-sarah-0.5}
        \mathbb{E}\Big[\|\mathcal{E}_{s,k}\|^2\,\big|\,x_{s,0}\Big]  \leq  \sum_{j=0}^{k-1} \mathbb{E}\bigg[\frac{1}{bn}\sum_{i=1}^n\|\nabla f_i(x_{s,j+1})-\nabla f_i(x_{s,j})\|^2\,\big|\,x_{s,0}\bigg].
    \end{equation}
    Because each $f_i$ is $L_i$-smooth adaptable to the KC-regular kernel $h$, applying the Lipschitz-like bound \eqref{prop:Lipschitz} to each $f_i$ on   $\bar{x}_{s,j+1}, x_{s,j}$ and their interpolation ${x}_{s,j+1} = \gamma\bar{x}_{s,j+1} + (1-\gamma)x_{s,j}$ immediately yields 
    \begin{eqnarray}
    \label{lm:err-sarah-1}
    \mathbb{E}\left[\frac{\|\mathcal{E}_{s,k}\|^2}{\mu_h(\mathcal{X}_s)}\,\Big|\, x_{s,0}\right] 
    &\leq&  \sum_{j=0}^{k-1}\mathbb{E}\bigg[ \frac{\sum_{i=1}^nL_i^2}{n}\cdot\frac{2\gamma^2  \kappa_h^2(\cX_s)}{b}D_h(\bar{x}_{s,j+1},x_{s,j})\,\big|\,x_{s,0}\bigg]\nonumber.
\end{eqnarray}
Using the fact that $L^2 = \frac{1}{n}\sum_{i=1}^nL_i^2$ and the fact that $\kappa_h(\cX_s)\leq \kappa_h^\delta$ leads to \eqref{lm:err-sarah-0}. 
\end{proof}

\begin{lemma}
    \label{lemma:proxSARAH-grad-map-mid}
    For any $b,\tau\in\mathbb{Z}_+$, set $\eta = \frac{\sqrt{2\tau}}{\sqrt{7\tau}+\sqrt{2b}}$, $\gamma = \frac{\sqrt{b}}{L\kappa_h^\delta\sqrt{\tau}}$, and $|\mathcal{B}_{s,k}|=b$, $\forall s,k\geq1$, then
    $$\mathbb{E}\left[\sum_{s=1}^S\sum_{k=0}^{\tau_s-1}\frac{\mu_h(\mathcal{X}_s)}{8}\big\|\cGshe(x_{s,k})\big\|^2 +D_h(\bar{x}_{s,k+1},x_{s,k}) \right]\leq \frac{\Delta_\Psi}{\gamma\eta},$$
    where $\Delta_\Psi:=\Psi(x_{1,0})-\inf\{\Psi(x):x\in\RR^d\}$ denotes the initial function value gap. 
\end{lemma}

\begin{lemma}
\label{lemma:event-halway} 
For any $S$ epochs  generated by Algorithm \ref{algorithm:proxSARAH}, define the set $\mathcal{I}_1$ and event $\mathcal{A}_1(m_1)$ as  
$$\mathcal{I}_1:=\big\{s\in[S] :  \tau_s < \tau\big\}\qquad\mbox{and}\qquad\mathcal{A}_1(m_1):=\left\{\omega: |\mathcal{I}_1|\geq m_1\right\}.$$
where $m_1>0$ is an arbitrary positive number. Then it holds that 
$$\mathrm{Prob}\left(\mathcal{A}_1(m_1)\right)\leq \frac{32\gamma\tau\Delta_\Psi}{\eta\mu\delta^2\cdot m_1}\,.$$
\end{lemma}

\begin{proof}
By lemma \ref{lemma:proxSARAH-grad-map-mid}, ignoring the restricted primal gradient mapping terms yields   
\begin{eqnarray}
    \label{lm:event-halfway-1}
    \frac{\Delta_\Psi}{\gamma\eta} &\geq& \mathbb{E}\left[\sum_{s=1}^S\sum_{k=0}^{\tau_s-1}D_h(\bar{x}_{s,k+1},x_{s,k}) \right]\nonumber\\ 
    & \geq & \mathbb{E}\left[\frac{\mu}{2\gamma^2}\sum_{s\in\mathcal{I}_1}\sum_{k=0}^{\tau_s-1}\|{x}_{s,k+1}-x_{s,k}\|^2 \right] \\
    & \geq & \frac{\mu}{2\gamma^2}\cdot \mathrm{Prob}\left(\mathcal{A}_1(m_1)\right) \cdot\mathbb{E}\left[\sum_{s\in\mathcal{I}_1}\sum_{k=0}^{\tau_s-1}\|{x}_{s,k+1}-x_{s,k}\|^2\,\Big|\, \mathcal{A}_1(m_1) \right] \nonumber,
\end{eqnarray}
where the last inequality is due to the fact that   
$$\EE[X] = \mathrm{Prob}(\cA)\cdot\EE\big[X\mid\cA\big] + \mathrm{Prob}(\cA^c)\cdot\EE\big[X\mid\cA^c\big]\geq \mathrm{Prob}(\cA)\cdot\EE\big[X\mid\cA\big]$$
for any non-negative random variable $X\geq0$ and any event $\cA$. Therefore, conditioning on the event $\mathcal{A}_1(m_1)$, for any epoch $s\in\mathcal{I}_1$, we will have $\|x_{s,\tau_s}-x_{s,0}\|\geq\frac{\delta}{4}$ because of Line 3 and Line 9 of Algorithm \ref{algorithm:proxSARAH}. Consequently, for $\forall s\in\mathcal{I}_1$, the triangle inequality and the arithmetic inequality indicate that
\begin{equation}
    \label{lm:event-halfway-2}
    \frac{\delta}{4\tau_s}\leq \frac{\|x_{s,\tau_s}-x_{s,0}\|}{\tau_s}\leq\frac{\sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|}{\tau_s}\leq  \sqrt{\frac{\sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|^2}{\tau_s}}\,.
\end{equation} 
Because $\tau_s\leq\tau$ always holds, we have 
\begin{align}
    \label{lm:event-halfway-3}
    \sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|^2  \geq  \sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|^2\geq\frac{\delta^2}{16\tau_s}\geq\frac{\delta^2}{16\tau}\,.
\end{align}
Note that the above inequalities hold w.p. 1 conditioning on $\cA_1(m_1)$. Combined with \eqref{lm:event-halfway-1}, we have 
$$\frac{\Delta_\Psi}{\gamma\eta} \geq\frac{\mu}{2\gamma^2}\cdot \mathrm{Prob}\left(\mathcal{A}_1(m_1)\right)\cdot\frac{m_1\delta^2}{16\tau}.$$
Rearranging the terms completes the proof. 
\end{proof}

\begin{lemma}
    \label{lemma:event-grad-map}
    For any $S$ epochs generated by Algorithm \ref{algorithm:proxSARAH}, define the set $\mathcal{I}_2$ and event $\mathcal{A}_2(m_2)$ as
    $$\mathcal{I}_2:=\left\{(s,k) :  \hat{x}_{s,k+1}\in\partial \mathcal{X}_s, 1\leq s\leq S, 0\leq k\leq \tau_s-1\right\}\quad\mbox{and}\quad\mathcal{A}_2(m_2):=\big\{\omega : |\mathcal{I}_2|\geq m_2\big\}$$
    where  $m_2>0$ is an arbitrary positive number. Then it holds that 
    $$\mathrm{Prob}\left(\mathcal{A}_2(m_2)\right)\leq \frac{128\eta\Delta_\Psi}{\gamma\mu\delta^2\cdot m_2}\,.$$
\end{lemma}

\begin{proof}
Similar to the proof of Lemma \ref{lemma:event-halway}, ignoring the Bregman divergence terms in Lemma \ref{lemma:proxSARAH-grad-map-mid} yields   
\begin{eqnarray}
    \label{lm:event-grad-map-1}
    \frac{\Delta_\Psi}{\gamma\eta} & \geq & \mathbb{E}\left[\sum_{s=1}^S\sum_{k=0}^{\tau_s-1}\frac{\mu}{8}\big\|\cGshe(x_{s,k})\big\|^2\right]\nonumber\\
    & = & \frac{\mu}{8\eta^2}\mathbb{E}\left[\sum_{s=1}^S\sum_{k=0}^{\tau_s-1}\|\hat{x}_{s,k+1}-x_{s,k}\|^2\right]\\
    & \geq & \frac{\mu}{8\eta^2}\mathbb{E}\Bigg[\sum_{(s,k)\in\mathcal{I}_2} \|\hat{x}_{s,k+1}-x_{s,k}\|^2\Bigg]\nonumber\\
    & \geq & \frac{\mu}{8\eta^2}\cdot\mathrm{Prob}\left(\mathcal{A}_2(m_2)\right)\cdot\mathbb{E}\Bigg[\sum_{(s,k)\in\mathcal{I}_2}\|\hat{x}_{s,k+1}-x_{s,k}\|^2\,\Big|\,\mathcal{A}_2(m_2)\Bigg]\nonumber.
\end{eqnarray}
Note that for  $\forall(s,k)\in\mathcal{I}_2$, we have $\mathrm{dist}(x_{s,k},\partial\cX_s)\geq\delta/4$ while $\hat{x}_{s,k+1}\in\partial\cX_s$. Consequently, one must have $\|\hat{x}_{s,k+1}-{x}_{s,k}\|\geq 
\frac{\delta}{4}$. Conditioning on the event $\cA_2(m_2)$, we have $|\mathcal{I}_2|\geq m_2$ and 
$$\mathbb{E}\Bigg[\sum_{(s,k)\in\mathcal{I}_2}\|\hat{x}_{s,k+1}-x_{s,k}\|^2\,\Big|\,\mathcal{A}_2(m_2)\Bigg]\geq \frac{m_2\delta^2}{16}.$$
Substitute this bound to \eqref{lm:event-grad-map-1} proves lemma.  
\end{proof}

\begin{proof}
By lemma \ref{lemma:proxSARAH-grad-map-mid}, ignoring the restricted primal gradient mapping terms yields  
\begin{eqnarray} 
\frac{\Delta_\Psi}{\gamma\eta} \geq
\mathbb{E}\bigg[\sum_{s=1}^{S}\sum_{k=0}^{\tau_s-1}D_h(\bar{x}_{s,k+1},x_{s,k})\bigg] 
\geq \frac{\mu}{2\gamma^2}\mathbb{E}\bigg[\sum_{s=1}^{S}\sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|^2\bigg]\,. \nonumber
\end{eqnarray}

By expanding the expectation over all possible $\mathcal{I}_1, \mathcal{I}_2,$ and $\{\tau_s\}$, we have for all $m_1,m_2>0$ that 
\begin{eqnarray} 
\label{thm:proxSARAH-finite-1}
\frac{2\gamma\Delta_\Psi}{\mu\eta} \!\!\!\!& \geq & \!\!\!\!\mathbb{E}\bigg[\sum_{s=1}^{S}\sum_{k=0}^{\tau_s-1}\!\|x_{s,k+1}\!-\!x_{s,k}\|^2\bigg] \\
& \geq &\!\!\!\! \sum_{|\mathcal{I}_1|<m_1}\sum_{|\mathcal{I}_2|< m_2}\sum_{\tau_s\in[\tau-1],s\in\mathcal{I}_1}\!\!\mathrm{Prob}\big(\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big)\mathbb{E}\bigg[\!\sum_{s=1}^S\!\sum_{k=0}^{\tau_s-1}\!\|x_{s,k+1}-x_{s,k}\|^2 \,\Big|\, \mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\!\bigg]\nonumber\\
& \geq &\!\!\!\! \sum_{|\mathcal{I}_1|<m_1}\sum_{|\mathcal{I}_2|< m_2}\sum_{\tau_s\in[\tau-1],s\in\mathcal{I}_1}\!\!\mathrm{Prob}\big(\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big)\mathbb{E}\bigg[\!\sum_{s\in\mathcal{I}_1}\!\!\sum_{k=0}^{\tau_s-1}\!\|x_{s,k+1}-x_{s,k}\|^2 \,\Big|\, \mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\!\bigg]\nonumber 
\end{eqnarray}
Note that for $\forall s\in\mathcal{I}_1$, according to the discussion in Lemma \ref{lemma:event-grad-map}, we have  $\|x_{s,\tau_s}-x_{s,0}\|  \geq \delta/4.$
Repeating the analysis of \eqref{lm:event-halfway-2} and \eqref{lm:event-halfway-3} yields $\sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|^2  \geq \frac{\delta^2}{16\tau_s}$, which always holds true. Then substituting this lower bound to \eqref{thm:proxSARAH-finite-1} gives 
\begin{equation}
    \label{thm:proxSARAH-finite-2}
    \sum_{|\mathcal{I}_1|<m_1}\sum_{|\mathcal{I}_2|< m_2}\sum_{\tau_s\in[\tau-1],s\in\mathcal{I}_1}\mathrm{Prob}\big(\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big)\cdot\sum_{s\in\mathcal{I}_1}\tau_s^{-1}\leq\frac{32\gamma\Delta_\Psi}{\mu\eta\delta^2}\,.
\end{equation} 
Define the events  
\begin{equation}
    \label{defn:event-A3}
    \mathcal{A}_3:=\big\{\omega: \mbox{the index of } x_{\mathrm{out}}\mbox{ is from }\mathcal{I}_2^c\big\}\quad\mbox{and}\quad \mathcal{A}:=\mathcal{A}_1^c(m_1)\cap\mathcal{A}_2^c(m_2)\cap\mathcal{A}_3.
\end{equation} 
Then we have
\begin{eqnarray}
    \label{thm:proxSARAH-finite-33}
    \!\!\!\!\!\!\!\!\!\!\mathrm{Prob}\left(\mathcal{A}\right)\!\!\! &=&\!\!\! \sum_{|\mathcal{I}_1|<m_1}\sum_{|\mathcal{I}_2|< m_2}\sum_{\tau_s\in[\tau-1],s\in\mathcal{I}_1}\mathrm{Prob}\big(\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big)\cdot\mathrm{Prob}\big(\cA_3\mid\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big)\\
    &=&\!\!\! \sum_{|\mathcal{I}_1|<m_1}\sum_{|\mathcal{I}_2|< m_2}\sum_{\tau_s\in[\tau-1],s\in\mathcal{I}_1}\mathrm{Prob}\big(\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big)\cdot\left(1-\frac{|\mathcal{I}_2|}{(S-|\mathcal{I}_1|)\tau+\sum_{s\in\mathcal{I}_1}\tau_s}\right)\nonumber\\
    & \geq &\!\!\! \sum_{|\mathcal{I}_1|<m_1}\sum_{|\mathcal{I}_2|< m_2}\sum_{\tau_s\in[\tau-1],s\in\mathcal{I}_1}\mathrm{Prob}\big(\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big)\cdot\left(1-\frac{m_2}{(S-|\mathcal{I}_1|)\tau+\sum_{s\in\mathcal{I}_1}\tau_s}\right).\nonumber
\end{eqnarray}
Note that for any positive numbers $y_1,\cdots,y_S>0$,  the arithmetic-harmonic inequality states that $$\frac{y_1+y_2+\cdots+y_S}{S}\geq\frac{S}{\frac{1}{y_1}+\frac{1}{y_2}+\cdots+\frac{1}{y_S}}\,.$$ 
Applying this inequality gives 
$$\frac{1}{\tau} + \frac{\sum_{s\in\mathcal{I}_1}\tau_s^{-1}}{S}= \frac{(S-|\mathcal{I}|_1)\tau^{-1} + \sum_{s\in\mathcal{I}_1}\tau_s^{-1}}{S}\geq \frac{S}{(S-|\mathcal{I}|_1)\tau+ \sum_{s\in\mathcal{I}_1}\tau_s}\,,$$
which implies that 
$$1-\frac{m_2}{(S-|\mathcal{I}_1|)\tau+\sum_{s\in\mathcal{I}_1}\tau_s}\geq 1-\frac{m_2}{S\tau}-\frac{m_2}{S^2}\sum_{s\in\mathcal{I}_1}\tau_s^{-1}\,.$$
Substituting this bound to \eqref{thm:proxSARAH-finite-33} and setting $m_1^* = S/4$ yields
\begin{eqnarray}
    \label{thm:proxSARAH-finite-44}
    \!\!\!\mathrm{Prob}\left(\mathcal{A}\right) \!\!\!\!& \geq &\!\!\!\! \sum_{|\mathcal{I}_1|<m_1^*}\sum_{|\mathcal{I}_2|< m_2}\sum_{\tau_s\in[\tau-1],s\in\mathcal{I}_1}\mathrm{Prob}\big(\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big)\cdot\left(1-\frac{m_2}{S\tau}-\frac{m_2}{S^2}\sum_{s\in\mathcal{I}_1}\tau_s^{-1}\right)\nonumber\\
    & \overset{(i)}{\geq} &\!\!\!\! \left(1-\frac{m_2}{S\tau}\right)\mathrm{Prob}\left(\mathcal{A}_1^c(m_1^*)\cap\mathcal{A}_2^c(m_2)\right) - \frac{m_2}{S^2}\cdot\frac{32\gamma\Delta_\Psi}{\mu\eta\delta^2}\\
    & \geq & \!\!\!\! \left(1-\frac{m_2}{S\tau}\right)\big(1-\mathrm{Prob}\left(\mathcal{A}_1(m_1^*)\right)-\mathrm{Prob}\left(\mathcal{A}_2(m_2)\right)\big) - \frac{m_2}{S^2}\cdot\frac{32\gamma\Delta_\Psi}{\mu\eta\delta^2}\nonumber\\
    & \overset{(ii)}{\geq} & \!\!\!\! 1 - \frac{8\eta\tau b\epsilon}{L^2(\kappa_h^\delta)^2\delta^2} - \frac{128\eta\Delta_\Psi}{\gamma\mu\delta^2\cdot m_2} - \frac{m_2}{S\tau} - \frac{m_2}{S^2}\cdot\frac{32\gamma\Delta_\Psi}{\mu\eta\delta^2}\nonumber\\
    & \overset{(iii)}{\geq} & \!\!\!\! 1 - \frac{8\eta\tau b\epsilon}{L^2(\kappa_h^\delta)^2\delta^2} - \frac{128\eta\Delta_\Psi}{m_2\gamma\mu\delta^2} - \frac{9m_2}{8S\tau}\nonumber
\end{eqnarray}
where (i) is due to \eqref{thm:proxSARAH-finite-2} and the fact that 
\begin{equation}
    \label{thm:proxSARAH-finite-55}
    \sum_{|\mathcal{I}_1|<m_1^*}\sum_{|\mathcal{I}_2|< m_2}\sum_{\tau_s\in[\tau-1],s\in\mathcal{I}_1}\mathrm{Prob}\big(\mathcal{I}_1,\mathcal{I}_2,\{\tau_s\}_{s\in\mathcal{I}_1}\big) = \mathrm{Prob}\big(\mathcal{A}_1^c(m_1^*)\cap\mathcal{A}_2^c(m_2)\big)
\end{equation}
(ii) is due to Lemma \ref{lemma:event-halway} with $m_1^*=S/4$ and $S = \big\lceil\frac{16\Delta_\Psi}{\tau\gamma\eta\mu\epsilon}\big\rceil$: 
$$\mathrm{Prob}\big(\mathcal{A}_1(S/4)\big)\leq \frac{32\gamma\tau\Delta_\Psi}{\mu\delta^2S/4} = \frac{16\Delta_\Psi}{S\tau\gamma\eta\mu}\cdot\frac{8\gamma^2\tau^2\eta}{\delta^2} \leq \frac{8\tau b\epsilon}{L^2(\kappa_h^\delta)^2\delta^2},$$
and (iii) is because we require $\epsilon\leq \frac{\delta^2}{16}\cdot\min\left\{\frac{L^2(\kappa_h^\delta)^2}{b\tau},\frac{1}{9\eta^2}\right\} = O(1/n)$ such that 
$$\frac{m_2}{S^2}\cdot\frac{32\gamma\Delta_\Psi}{\mu\eta\delta^2} = \frac{m_2}{S\tau}\cdot\frac{16\Delta_\Psi}{S\tau\gamma\eta\mu}\cdot\frac{2\gamma^2\tau^2}{\delta^2}\leq \frac{m_2}{8S\tau}$$
Therefore, to maximize the above probability, we can choose $m_2^*=\sqrt{\frac{S\tau\eta\Delta_\Psi}{\gamma\mu}}\cdot\frac{32}{3\delta}$ such that
$$\frac{128\eta\Delta_\Psi}{m_2^*\gamma\mu\delta^2} + \frac{9m_2^*}{8S\tau} = 2\sqrt{\frac{128\eta\Delta_\Psi}{m_2^*\gamma\mu\delta^2} \cdot  \frac{9m_2^*}{8S\tau}} = \sqrt{\frac{\eta\Delta_\Psi}{\gamma\mu S\tau}}\cdot\frac{24}{\delta}\leq \frac{6\eta\sqrt{\epsilon}}{\delta}\leq \frac{4\sqrt{\epsilon}}{\delta}\,, $$
where the last inequality is due to the fact that $\eta = \frac{\sqrt{2\tau}}{\sqrt{7\tau}+\sqrt{2b}}\leq\sqrt{2/7}.$ Combining all the above discussion, we can conclude that  
$$\mathrm{Prob}\left(\mathcal{A}\right)\geq1 - \frac{8\eta\tau b\epsilon}{L^2(\kappa_h^\delta)^2\delta^2}-\frac{4\sqrt{\epsilon}}{\delta} = 1-O(n\epsilon+\sqrt{\epsilon})$$
when taking $m_1^* = S/4$ and $m_2^* = \sqrt{\frac{S\tau\eta\Delta_\Psi}{\gamma\mu}}\cdot\frac{32}{3\delta}.$ Note that the requirement on $\epsilon$ further implies that $\mathrm{Prob}(\cA_1(m_1^*))\leq 1/2$ and $\mathrm{Prob}(\cA_2(m_2^*))\leq 1/4$, and hence $\mathrm{Prob}\big(\cA_1^c(m_1^*)\cap\cA_2^c(m_2^*)\big)\geq1/4$. By ignoring the Bregman divergence terms of Lemma \ref{lemma:proxSARAH-grad-map-mid}, we obtain
\begin{eqnarray*}
    \frac{\Delta_\Psi}{\gamma\eta} &\geq& \frac{\mu}{8} \mathbb{E}\bigg[\sum_{s=1}^S\sum_{k=0}^{\tau_s-1}\big\|\cGshe(x_{s,k})\big\|^2\bigg]  \geq \frac{\mu}{32}\mathbb{E}\bigg[\sum_{(s,k)\in\mathcal{I}_2^c}\big\|\cGshe(x_{s,k})\big\|^2\,\Big|\,\cA_1^c(m_1^*)\cap\cA_2^c(m_2^*)\bigg] \nonumber.
\end{eqnarray*}
Conditioning on $\cA_1^c(m_1^*)\cap\cA_2^c(m_2^*)$, regardless of the random sets $\mathcal{I}_1, \mathcal{I}_2$ and $\{\tau_s\}_{s\in\mathcal{I}_1}$, we have  
\begin{eqnarray}
    |\mathcal{I}_2^c| = (S-|\mathcal{I}_1|)\tau+\sum_{s\in\mathcal{I}_1}\tau_s - |\mathcal{I}_2|\geq  \frac{3S\tau}{4} - m_2^*\geq S\tau\Big(\frac{3}{4}-\frac{8\eta\sqrt{\epsilon}}{3\delta}\Big) \geq \frac{S\tau}{2}.\nonumber
\end{eqnarray}
where the second last inequality is because $|\mathcal{I}_2|\leq m_2^*\leq \frac{8S\tau\eta\sqrt{\epsilon}}{3\delta}$, and the last inequality is because  $\frac{8\eta\sqrt{\epsilon}}{3\delta}\leq 2/9< 1/4$ since we require $\epsilon\leq\frac{\delta^2}{16}\cdot\frac{1}{9\eta^2}$. As a result, 
\begin{eqnarray}
\label{thm:proxSARAH-finite-66}
    \frac{\Delta_\Psi}{\gamma\eta} &\geq& \frac{\mu}{32}\cdot\frac{S\tau}{2}\cdot\mathbb{E}\bigg[\frac{|\mathcal{I}_2^c|}{S\tau/2}\cdot\frac{\sum_{(s,k)\in\mathcal{I}_2^c}\big\|\cGshe(x_{s,k})\big\|^2}{|\mathcal{I}_2^c|}\,\Big|\,\cA_1^c(m_1^*)\cap\cA_2^c(m_2^*)\bigg] \\
    & \geq & \frac{\mu S\tau}{64}\mathbb{E}\bigg[\frac{\sum_{(s,k)\in\mathcal{I}_2^c}\big\|\cGshe(x_{s,k})\big\|^2}{|\mathcal{I}_2^c|}\,\Big|\,\cA_1^c(m_1^*)\cap\cA_2^c(m_2^*)\bigg] \nonumber\\
    & = & \frac{\mu S\tau}{64}\mathbb{E}\Big[\big\|\cGphe(x_{\mathrm{out}})\big\|^2\,\big|\,\cA_1^c(m_1^*)\cap\cA_2^c(m_2^*)\cap\cA_3\Big]\,, \nonumber
\end{eqnarray}
where the last equality is due to the definition of $x_{\mathrm{out}}$, $\cA_3$, and the fact that $\cGshe(\cdot)$ coincides with $\cGphe(\cdot)$ in $\mathcal{I}_2^c$. As a result, we have
$$\mathbb{E}\Big[\big\|\cGphe(x_{\mathrm{out}})\big\|^2\,\big|\,\cA\Big]\leq \frac{64\Delta_\Psi}{\gamma\eta\mu\tau S}\leq 4\epsilon.$$
Given the choice of $S$, $\gamma$, $\eta$, and the fact that $\tau = \lceil n/b\rceil$, the total sample complexity will be 
$$S(n+b\tau) = (n+b\tau)\cdot\bigg\lceil\frac{16\Delta_\Psi}{\tau\gamma\eta\mu\epsilon}\bigg\rceil = O\left(\frac{L\kappa_h^\delta\Delta_\Psi\sqrt{n}}{\mu\epsilon}\cdot\Big(1+\sqrt{b/\tau}\Big)\right),$$
which indicates an $O(\sqrt{n}\epsilon^{-1})$ sample complexity for all $b\leq O(\tau)$ (or equivalently, $b\leq O(\lceil\sqrt{n}\rceil)$). If larger batch size $b = \lceil n^\alpha\rceil$ with $\alpha\in(1/2,1]$ is taken, then we obtain an $O(n^\alpha\epsilon^{-1})$ complexity. 
\end{proof}

\begin{lemma}[Lemma 2 finite-sum case of \cite{pham2020proxsarah}]
\label{lemma:proxSARAH-finite-sum}
    Let $v_{s,k}$ be generated by \eqref{alg:sarah-small}, suppose $|\mathcal{B}_{s,k}| = b$ and the sampled index are uniformly randomly picked from $[n]$ with replacement, then  
    \begin{eqnarray}
        \mathbb{E}\Big[\|\nabla f(x_{s,k})-v_{s,k}\|^2\,\big|\,x_{s,0}\Big] \leq \sum_{j=0}^{k-1} \mathbb{E}\Big[\|v_{s,j+1}-v_{s,j}\|^2-\|\nabla f(x_{s,j+1})-\nabla f(x_{s,j})\|^2\,\big|\, x_{s,0}\Big], \nonumber 
    \end{eqnarray}
    where the expectation term of $\|v_{s,j+1}-v_{s,j}\|^2$ satisfies
    \begin{eqnarray}
        \mathbb{E}\Big[\|v_{s,j+1}-v_{s,j}\|^2\,\big|\,x_{s,0}\Big] \leq  \mathbb{E}\bigg[\|\nabla f(x_{s,j+1})-\nabla f(x_{s,j})\|^2 + \frac{1}{bn}\sum_{i=1}^n\|\nabla f_i(x_{s,j+1})-\nabla f_i(x_{s,j})\|^2\,\big|\,x_{s,0}\bigg].  \nonumber
    \end{eqnarray}  
    In particular, we have slightly modified the second inequality to suit our analysis. 
\end{lemma}

\begin{lemma}
    \label{lemma:B.1}
    Let $A$ be a symmetric matrix, and let $B\succeq0$ be positive semidefinite matrix. Then $-B\preceq A\preceq B$ indicates that $\|A\|\leq \|B\|$.
\end{lemma}

\begin{proof}
    For any symmetric but not semidefinite matrix $A$, it is easy to verify that 
    \begin{equation}
        \label{lm:B.1-1}
        \|A\| = \max\big\{|\lambda_{\max}(A)|,|\lambda_{\min}(A)|\big\}.
    \end{equation}
    Let $u\neq0$ be the eigenvector of $A$ associated with the maximum eigenvalue.  Then by Rayleigh’s principle for maximum eigenvalue, $B\succeq A$ indicates that $B-A\succeq0$ and hence 
    \begin{equation}
        \label{lm:B.1-2}
        0\leq \frac{u^\top(B-A)u}{u^\top u} \leq \max_{x\neq0}\left\{\frac{x^\top Bx}{x^\top x}\right\} - \frac{u^\top(B-A)u}{u^\top u} = \lambda_{\max}(B) - \lambda_{\max}(A). 
    \end{equation}
    Similarly, $A\succeq-B$ indicates that $B-(-A)\succeq0$, then \eqref{lm:B.1-2} immediately gives
    \begin{equation}
        \label{lm:B.1-3}
        0\leq  \lambda_{\max}(B) - \lambda_{\max}(-A) = \lambda_{\max}(B) + \lambda_{\min}(A).
    \end{equation}
    Combining \eqref{lm:B.1-1}-\eqref{lm:B.1-3} and the fact that $\|B\| = \lambda_{\max}(B)$ for p.s.d. matrix proves the lemma.
\end{proof}

\begin{proof}
    Denote $\widetilde{\mathcal{G}}=\frac{x_{s,k}-\bar{x}_{s,k+1}}{\eta}$, then $\|\cGshe(x_{s,k})-\widetilde{\mathcal{G}}\| = \frac{1}{\eta}\|\bar{x}_{s,k+1}-\hat{x}_{s,k+1}\|$ holds by definition. 
    By the optimality of $\hat{x}_{s,k+1}$ and $\bar{x}_{s,k+1}$ for the corresponding subproblems, Tseng's three point property (Lemma \ref{lemma:Tseng-3point}) indicates that
    \begin{eqnarray*}
        &&\langle v_{s,k}, \bar{x}_{s,k+1}\rangle + \phi(\bar{x}_{s,k+1}) + \frac{D_h(\bar{x}_{s,k+1},x_{s,k})}{\eta} + \frac{D_h(\hat{x}_{s,k+1},\bar{x}_{s,k+1})}{\eta}\qquad\,\,\,\\
        &\leq& \langle v_{s,k}, \hat{x}_{s,k+1}\rangle + \phi(\hat{x}_{s,k+1})+ \frac{D_h(\hat{x}_{s,k+1},x_{s,k})}{\eta} 
    \end{eqnarray*} 
    and 
    \begin{eqnarray*}
        && \langle \nabla f(x_{s,k}), \hat{x}_{s,k+1}\rangle + \phi(\hat{x}_{s,k+1})+\frac{D_h(\hat{x}_{s,k+1},x_{s,k})}{\eta} + \frac{D_h(\bar{x}_{s,k+1},\hat{x}_{s,k+1})}{\eta}\\
        &\leq& \langle \nabla f(x_{s,k}), \bar{x}_{s,k+1}\rangle + \phi(\bar{x}_{s,k+1})+\frac{D_h(\bar{x}_{s,k+1},x_{s,k})}{\eta}
    \end{eqnarray*} 
    Summing up the two inequalities and applying Lemma \ref{lemma:grd-vs-grdmap} gives 
    \begin{align} &\frac{\mu_h([\bar{x}_{s,k+1},\hat{x}_{s,k+1}])}{\eta}\cdot\|\bar{x}_{s,k+1}-\hat{x}_{s,k+1}\|^2 \leq \frac{D_h(\bar{x}_{s,k+1},\hat{x}_{s,k+1})}{\eta} +  \frac{D_h(\hat{x}_{s,k+1},\bar{x}_{s,k+1})}{\eta}\nonumber\\
    &\qquad\qquad\qquad\qquad\qquad\,\,\,\, \leq  \langle v_{s,k}-\nabla f(x_{s,k}), \hat{x}_{s,k+1}-\bar{x}_{s,k+1}\rangle \leq  \|v_{s,k}-\nabla f(x_{s,k})\|\cdot\|\hat{x}_{s,k+1}-\bar{x}_{s,k+1}\|\nonumber.
    \end{align} 
    Hence $\|\hat{x}_{s,k+1}-\bar{x}_{s,k+1}\|\leq \frac{\eta\|v_{s,k}-\nabla f(x_{s,k})\|}{\mu_h([\bar{x}_{s,k+1},\hat{x}_{s,k+1}])}$, and $\big\|\cGshe(x_{s,k})-\widetilde{\mathcal{G}}\big\|\leq\frac{\|v_{s,k}-\nabla f(x_{s,k})\|}{\mu_h([\bar{x}_{s,k+1},\hat{x}_{s,k+1}])}$. As a result, 
    \begin{eqnarray*}
        \big\|\cGshe(x_{s,k})\big\|^2 \leq \left(\big\|\widetilde{\mathcal{G}}\big\|+\big\|\cGshe(x_{s,k})-\widetilde{\mathcal{G}}\big\|\right)^2\leq  \frac{2\|x_{s,k}-\bar{x}_{s,k+1}\|^2}{\eta^2} + \frac{2\|v_{s,k}-\nabla f(x_{s,k})\|^2}{\mu_h^2(\mathcal{X}_s)},
    \end{eqnarray*} 
    where the last inequality is because $(a+b)^2\leq 2a^2+2b^2$ and $\mu_h^2\big([\bar{x}_{s,k+1},\hat{x}_{s,k+1}]\big)\geq\mu_h^2(\cX_s)$. 
\end{proof}

\begin{proof} 
    First of all, by the update rule of $x_{s,k+1}$, we have   
    \begin{eqnarray}
    \label{lm:descent-proxSARAH-finite-1}
        \Psi(x_{s,k+1}) 
        \!\!\!& = & \!\!\!f\big(x_{s,k} + \gamma (\bar{x}_{s,k+1}-x_{s,k})\big) + \phi\big((1-\gamma)x_{s,k} + \gamma\bar{x}_{s,k+1}\big) \\
        &\overset{(i)}{\leq}& \!\!\!f(x_{s,k}) + \gamma\langle\nabla f(x_{s,k}),\bar{x}_{s,k+1}\!-x_{s,k}\rangle \!+\! LD_h\left(x_{s,k+1},x_{s,k}\right) \!+\! (1-\gamma)\phi(x_{s,k})+\gamma\phi(\bar{x}_{s,k+1})\nonumber\\
        & \overset{(ii)}{\leq} & \!\!\!\Psi(x_{s,k}) + L\kappa_h^\delta\gamma^2D_h(\bar{x}_{s,k+1},x_{s,k}) + \gamma\langle\mathcal{E}_{s,k}+v_{s,k},\bar{x}_{s,k+1}-x_{s,k}\rangle  + \gamma\left(\phi(\bar{x}_{s,k+1})-\phi(x_{s,k})\right)\nonumber\\
        &\overset{(iii)}{\leq}&\!\!\! \Psi(x_{s,k}) + L\kappa_h^\delta\gamma^2D_h(\bar{x}_{s,k+1},x_{s,k}) + \frac{\gamma\eta\|\mathcal{E}_{s,k}\|^2}{\mu_h(\mathcal{X}_s)} + \frac{\gamma\mu_h(\mathcal{X}_s)}{4\eta} \|\bar{x}_{s,k+1}-x_{s,k}\|^2\nonumber\\
        & & \!\!\!-\frac{\gamma}{\eta}D_h(\bar{x}_{s,k+1},x_{s,k}) - \frac{\gamma}{\eta}D_h(x_{s,k},\bar{x}_{s,k+1})\nonumber\\
        &\leq & \!\!\!\Psi(x_{s,k}) - \left(\frac{\gamma}{\eta}- L\kappa_h^\delta\gamma^2\right)D_h(\bar{x}_{s,k+1},x_{s,k}) -\frac{\gamma}{2\eta}D_h(x_{s,k},\bar{x}_{s,k+1})+ \frac{\gamma\eta\|\mathcal{E}_{s,k}\|^2}{\mu_h(\mathcal{X}_s)} \,,\nonumber
    \end{eqnarray}
    where (i) is due to Assumption \ref{assumption:L-smad-finite-sum}, Lemma \ref{lemma:descent-lemma}, and the convexity of $\phi$, (ii) is due to the definition of $\mathcal{E}_{s,k}$ in Lemma \ref{lemma:restricted-grd-mapping} and the following scaling property
    \begin{eqnarray}
        D_h\left(x_{s,k+1},x_{s,k}\right)  \leq \frac{L_h(\mathcal{X}_s)}{2}\|x_{s,k+1}-x_{s,k}\|^2 = \frac{\gamma^2L_h(\mathcal{X}_s)}{2}\|\bar{x}_{s,k+1}-x_{s,k}\|^2 \leq \gamma^2\kappa_h^\delta D_h(\bar{x}_{s,k+1},x_{s,k})\,,\nonumber
    \end{eqnarray}
    and (iii) is due to the optimality of  $\bar{x}_{s,k+1}$ to the corresponding subproblem and Tseng's three point property (Lemma \ref{lemma:Tseng-3point}). Finally, by Lemma \ref{lemma:restricted-grd-mapping}, we also have
    $$\big\|\cGshe(x_{s,k})\big\|^2 \leq \frac{2\|x_{s,k}-\bar{x}_{s,k+1}\|^2}{\eta^2} + \frac{2\|\mathcal{E}_{s,k}\|^2}{\mu_h^2(\mathcal{X}_s)}\,.$$
    Multiplying both sides of the above inequality by $\frac{\gamma\eta\mu_h(\mathcal{X}_s)}{8}$ and add it to \eqref{lm:descent-proxSARAH-finite-1} proves the lemma. 
\end{proof}

\begin{proof}
    First, substituting the gradient estimation bound in Lemma \ref{lemma:err-sarah} to Lemma \ref{lemma:descent-proxSARAH-finite}, we have the following descent result throughout the $s$-th epoch

\begin{align}
    \label{lm:proxSARAH-grad-map-mid-1}
    &\mathbb{E}\Big[\Psi(x_{s,\tau_s}) \,\big|\, x_{s,0}\Big] \!\leq \Psi(x_{s,0}) \!-\! \mathbb{E}\bigg[\frac{\gamma\eta\mu_h(\mathcal{X}_s)}{8}\!\sum_{k=0}^{\tau_s-1}\!\big\|\cGshe(x_{s,k})\big\|^2 \!+\!\bigg(\!\frac{\gamma}{\eta}- L\kappa_h^\delta\gamma^2\!\bigg)D_h(\bar{x}_{s,k+1},x_{s,k}) \,\Big|\, x_{s,0}\bigg]\nonumber\\
    &\qquad\qquad\qquad\qquad\,\, +\frac{5\gamma\eta}{4\mu_h(\mathcal{X}_s)}\cdot\frac{2\gamma^2L^2\kappa_h^\delta L_h(\mathcal{X}_s)}{b}\mathbb{E}\bigg[\sum_{k=0}^{\tau_s-1}\sum_{j=0}^{k-1} D_h(\bar{x}_{s,j+1},x_{s,j}) \,\Big|\, x_{s,0}\bigg]\\
    &\quad\,\leq \Psi(x_{s,0}) \!-\! \mathbb{E}\bigg[\frac{\gamma\eta\mu_h(\mathcal{X}_s)}{8}\!\sum_{k=0}^{\tau_s-1}\big\|\mathcal{G}_{s,k}^\eta(x_{s,k})\big\|^2 \!+\bigg(\frac{\gamma}{\eta}- L\kappa_h^\delta\gamma^2-\frac{5\tau\gamma^3\eta L^2(\kappa_h^\delta)^2}{2b}\bigg)D_h(\bar{x}_{s,k+1},x_{s,k}) \,\Big|\, x_{s,0}\bigg]\nonumber
\end{align}

\noindent Suppose we choose $\eta  = \frac{\sqrt{2\tau}}{\sqrt{7\tau}+\sqrt{2b}}$ and we choose $\gamma = \frac{\sqrt{b}}{L\kappa_h^\delta\sqrt{\tau}}$. Then we have 
\begin{eqnarray}
    \label{lm:proxSARAH-grad-map-mid-2}
    &&\frac{\gamma}{\eta} - L\kappa_h^\delta\gamma^2 - \frac{5\tau\gamma^3\eta L^2(\kappa_h^\delta)^2}{2b}\nonumber\\
    & = & \gamma\eta\bigg(\frac{1}{\eta^2} - \frac{L\kappa_h^\delta\gamma}{\eta} - \frac{5\tau\gamma^2 L^2(\kappa_h^\delta)^2}{2b}\bigg)\\
    &=& \gamma\eta\bigg(1+\frac{\sqrt{14} -\sqrt{3.5}}{\sqrt{\tau/b}}\bigg)\nonumber \\
    &\geq& \gamma\eta\,.\nonumber
\end{eqnarray} 
Substitute the bound to the previous inequality, summing up over all epochs, and taking the expectation over all randomness proves the lemma. 
\end{proof}

