\end{proof}

\begin{lemma}
    \label{lemma:grd-vs-grdmap}
    For any $x,v\in\RR^d$ and any strictly convex kernel $h$, denote $x_\lambda^+(v) := \mathbf{T}_{\phi,h}^\lambda(x,v)$.  Let $[x,x_\lambda^+(v)]$ be the line segment between $x_\lambda^+(v)$ and $x$, then there exists $u\in\partial\phi(x_\lambda^+(v))$ such that  
    \begin{equation}
        \mu_h\big([x,x_\lambda^+(v)]\big)\cdot \|x-x_\lambda^+(v)\|\leq\lambda\|v+u\|\leq L_h\big([x,x_\lambda^+(v)]\big)\cdot \|x-x_\lambda^+(v)\|\,,\nonumber
    \end{equation} 
    \begin{equation}
        \sqrt{2\mu_h\big([x,x_\lambda^+(v)]\big)\cdot D_h(x_\lambda^+(v),x)}\leq \lambda\|v+u\|\leq \sqrt{2L_h\big([x,x_\lambda^+(v)]\big)\cdot D_h(x_\lambda^+(v),x)}\,\,.\nonumber
    \end{equation}   
\end{lemma}

\begin{proof}
    By the optimality condition of the subproblem $x_\lambda^+(v)=\argmin_{y\in\RR^d}\, y^\top v + \phi(y) + \frac{1}{\lambda}D_h(y,x)$, we have $0\in \partial\phi(x_\lambda^+(v))+v+\frac{1}{\lambda}\nabla_y D_h(y,x)|_{y=x_\lambda^+(v)}$. Namely, there exists  $u\in\partial\phi(x_\lambda^+(v))$ such that 
    \begin{equation}
        \label{lm:grd-vs-grdmap-1}
        \lambda(v + u) +  \big(\nabla h(x_\lambda^+(v))-\nabla h(x)\big)=0.
    \end{equation}

\begin{lemma}
\label{lemma:event-halway} 
For any $S$ epochs  generated by Algorithm \ref{algorithm:proxSARAH}, define the set $\mathcal{I}_1$ and event $\mathcal{A}_1(m_1)$ as  
$$\mathcal{I}_1:=\big\{s\in[S] :  \tau_s < \tau\big\}\qquad\mbox{and}\qquad\mathcal{A}_1(m_1):=\left\{\omega: |\mathcal{I}_1|\geq m_1\right\}.$$
where $m_1>0$ is an arbitrary positive number. Then it holds that 
$$\mathrm{Prob}\left(\mathcal{A}_1(m_1)\right)\leq \frac{32\gamma\tau\Delta_\Psi}{\eta\mu\delta^2\cdot m_1}\,.$$
\end{lemma}

\begin{proof}
By lemma \ref{lemma:proxSARAH-grad-map-mid}, ignoring the restricted primal gradient mapping terms yields   
\begin{eqnarray}
    \label{lm:event-halfway-1}
    \frac{\Delta_\Psi}{\gamma\eta} &\geq& \mathbb{E}\left[\sum_{s=1}^S\sum_{k=0}^{\tau_s-1}D_h(\bar{x}_{s,k+1},x_{s,k}) \right]\nonumber\\ 
    & \geq & \mathbb{E}\left[\frac{\mu}{2\gamma^2}\sum_{s\in\mathcal{I}_1}\sum_{k=0}^{\tau_s-1}\|{x}_{s,k+1}-x_{s,k}\|^2 \right] \\
    & \geq & \frac{\mu}{2\gamma^2}\cdot \mathrm{Prob}\left(\mathcal{A}_1(m_1)\right) \cdot\mathbb{E}\left[\sum_{s\in\mathcal{I}_1}\sum_{k=0}^{\tau_s-1}\|{x}_{s,k+1}-x_{s,k}\|^2\,\Big|\, \mathcal{A}_1(m_1) \right] \nonumber,
\end{eqnarray}
where the last inequality is due to the fact that   
$$\EE[X] = \mathrm{Prob}(\cA)\cdot\EE\big[X\mid\cA\big] + \mathrm{Prob}(\cA^c)\cdot\EE\big[X\mid\cA^c\big]\geq \mathrm{Prob}(\cA)\cdot\EE\big[X\mid\cA\big]$$
for any non-negative random variable $X\geq0$ and any event $\cA$. Therefore, conditioning on the event $\mathcal{A}_1(m_1)$, for any epoch $s\in\mathcal{I}_1$, we will have $\|x_{s,\tau_s}-x_{s,0}\|\geq\frac{\delta}{4}$ because of Line 3 and Line 9 of Algorithm \ref{algorithm:proxSARAH}. Consequently, for $\forall s\in\mathcal{I}_1$, the triangle inequality and the arithmetic inequality indicate that
\begin{equation}
    \label{lm:event-halfway-2}
    \frac{\delta}{4\tau_s}\leq \frac{\|x_{s,\tau_s}-x_{s,0}\|}{\tau_s}\leq\frac{\sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|}{\tau_s}\leq  \sqrt{\frac{\sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|^2}{\tau_s}}\,.
\end{equation} 
Because $\tau_s\leq\tau$ always holds, we have 
\begin{align}
    \label{lm:event-halfway-3}
    \sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|^2  \geq  \sum_{k=0}^{\tau_s-1}\|x_{s,k+1}-x_{s,k}\|^2\geq\frac{\delta^2}{16\tau_s}\geq\frac{\delta^2}{16\tau}\,.
\end{align}
Note that the above inequalities hold w.p. 1 conditioning on $\cA_1(m_1)$. Combined with \eqref{lm:event-halfway-1}, we have 
$$\frac{\Delta_\Psi}{\gamma\eta} \geq\frac{\mu}{2\gamma^2}\cdot \mathrm{Prob}\left(\mathcal{A}_1(m_1)\right)\cdot\frac{m_1\delta^2}{16\tau}.$$
Rearranging the terms completes the proof. 
\end{proof}

