\begin{lemma}
    \label{lemma:event-grad-map}
    For any $S$ epochs generated by Algorithm \ref{algorithm:proxSARAH}, define the set $\mathcal{I}_2$ and event $\mathcal{A}_2(m_2)$ as
    $$\mathcal{I}_2:=\left\{(s,k) :  \hat{x}_{s,k+1}\in\partial \mathcal{X}_s, 1\leq s\leq S, 0\leq k\leq \tau_s-1\right\}\quad\mbox{and}\quad\mathcal{A}_2(m_2):=\big\{\omega : |\mathcal{I}_2|\geq m_2\big\}$$
    where  $m_2>0$ is an arbitrary positive number. Then it holds that 
    $$\mathrm{Prob}\left(\mathcal{A}_2(m_2)\right)\leq \frac{128\eta\Delta_\Psi}{\gamma\mu\delta^2\cdot m_2}\,.$$
\end{lemma}

\begin{proof}
Similar to the proof of Lemma \ref{lemma:event-halway}, ignoring the Bregman divergence terms in Lemma \ref{lemma:proxSARAH-grad-map-mid} yields   
\begin{eqnarray}
    \label{lm:event-grad-map-1}
    \frac{\Delta_\Psi}{\gamma\eta} & \geq & \mathbb{E}\left[\sum_{s=1}^S\sum_{k=0}^{\tau_s-1}\frac{\mu}{8}\big\|\cGshe(x_{s,k})\big\|^2\right]\nonumber\\
    & = & \frac{\mu}{8\eta^2}\mathbb{E}\left[\sum_{s=1}^S\sum_{k=0}^{\tau_s-1}\|\hat{x}_{s,k+1}-x_{s,k}\|^2\right]\\
