    & \geq & \frac{\mu}{8\eta^2}\cdot\mathrm{Prob}\left(\mathcal{A}_2(m_2)\right)\cdot\mathbb{E}\Bigg[\sum_{(s,k)\in\mathcal{I}_2}\|\hat{x}_{s,k+1}-x_{s,k}\|^2\,\Big|\,\mathcal{A}_2(m_2)\Bigg]\nonumber.
\end{eqnarray}
Note that for  $\forall(s,k)\in\mathcal{I}_2$, we have $\mathrm{dist}(x_{s,k},\partial\cX_s)\geq\delta/4$ while $\hat{x}_{s,k+1}\in\partial\cX_s$. Consequently, one must have $\|\hat{x}_{s,k+1}-{x}_{s,k}\|\geq 
\frac{\delta}{4}$. Conditioning on the event $\cA_2(m_2)$, we have $|\mathcal{I}_2|\geq m_2$ and 
$$\mathbb{E}\Bigg[\sum_{(s,k)\in\mathcal{I}_2}\|\hat{x}_{s,k+1}-x_{s,k}\|^2\,\Big|\,\mathcal{A}_2(m_2)\Bigg]\geq \frac{m_2\delta^2}{16}.$$
Substitute this bound to \eqref{lm:event-grad-map-1} proves lemma.  
\end{proof}

