\begin{lemma}[Lemma 2 finite-sum case of \cite{pham2020proxsarah}]
\label{lemma:proxSARAH-finite-sum}
    Let $v_{s,k}$ be generated by \eqref{alg:sarah-small}, suppose $|\mathcal{B}_{s,k}| = b$ and the sampled index are uniformly randomly picked from $[n]$ with replacement, then  
    \begin{eqnarray}
        \mathbb{E}\Big[\|\nabla f(x_{s,k})-v_{s,k}\|^2\,\big|\,x_{s,0}\Big] \leq \sum_{j=0}^{k-1} \mathbb{E}\Big[\|v_{s,j+1}-v_{s,j}\|^2-\|\nabla f(x_{s,j+1})-\nabla f(x_{s,j})\|^2\,\big|\, x_{s,0}\Big], \nonumber 
    \end{eqnarray}
    where the expectation term of $\|v_{s,j+1}-v_{s,j}\|^2$ satisfies
    \begin{eqnarray}
        \mathbb{E}\Big[\|v_{s,j+1}-v_{s,j}\|^2\,\big|\,x_{s,0}\Big] \leq  \mathbb{E}\bigg[\|\nabla f(x_{s,j+1})-\nabla f(x_{s,j})\|^2 + \frac{1}{bn}\sum_{i=1}^n\|\nabla f_i(x_{s,j+1})-\nabla f_i(x_{s,j})\|^2\,\big|\,x_{s,0}\bigg].  \nonumber
    \end{eqnarray}  
    In particular, we have slightly modified the second inequality to suit our analysis. 
\end{lemma}
